import ButtonGroup from "@marko-ui/shadcn/ui/button-group/button-group.marko";
import Button from "@marko-ui/shadcn/ui/button/button.marko";
import TextInput from "@marko-ui/shadcn/ui/input/input.marko";
import Icon from "@marko-ui/shadcn/ui/icon/icon.marko";

<ButtonGroup>
  <TextInput placeholder="Search..."/>
  <Button type="button" variant="outline" aria-label="Search">
    <Icon name="SearchIcon"/>
  </Button>
</ButtonGroup>

import ButtonGroup from "@marko-ui/shadcn/ui/button-group/button-group.marko";
import Button from "@marko-ui/shadcn/ui/button/button.marko";
import TextInput from "@marko-ui/shadcn/ui/input/input.marko";
import Select from "@marko-ui/shadcn/ui/select/select.marko";
import Icon from "@marko-ui/shadcn/ui/icon/icon.marko";

static const CURRENCIES = [
  { value: "$", label: "US Dollar" },
  { value: "€", label: "Euro" },
  { value: "£", label: "British Pound" },
];

<let/currency=["$"]/>

<ButtonGroup>
  <ButtonGroup>
    <Select
      items=CURRENCIES
      value=currency
      valueChange=(next) => { currency = next; }
    />
    <TextInput placeholder="10.00" pattern="[0-9]*"/>
  </ButtonGroup>
  <ButtonGroup>
    <Button type="button" aria-label="Send" size="icon" variant="outline">
      <Icon name="ArrowRightIcon"/>
    </Button>
  </ButtonGroup>
</ButtonGroup>

import ButtonGroup from "@marko-ui/shadcn/ui/button-group/button-group.marko";
import ButtonGroupText from "@marko-ui/shadcn/ui/button-group/text.marko";
import Button from "@marko-ui/shadcn/ui/button/button.marko";

<ButtonGroup>
  <ButtonGroupText>Page 1 of 10</ButtonGroupText>
  <Button type="button" variant="outline">Prev</Button>
  <Button type="button" variant="outline">Next</Button>
</ButtonGroup>
